data.transform:
(
  $model := $executeTransform("getModelByName", {
    "api": $state.context.parameters.api,
    "name": $state.context.parameters.modelName
  });

  {
    "model": $model ? 
      $model : 
      $throw($state.context.parameters.modelName & ' is not present in the model map.  See if the model name is misspelled, or if you specified the wrong API, or if there is no model definition within the schema folder of that API.')
  }
)

(
  $hide := [
    'dataChanges',
    'createdAt',
    'createdByUser',
    'createdByUserId',
    'updatedAt',
    'updatedByUser',
    'updatedByUserId',
    'id'
  ];

  $hideFormats := [
    'json'
  ];

  $columns := columns@$v.{
    "name": $v.name,
    "visible": $exists($hide[$=$v.name]) = false 
      and $exists($hideFormats[$=$v.format]) = false 
      and $substringAfter($v.name, 'Id') != ''
  };

  $filters := filters@$v.{
    "name": $v.name,
    "visible": $exists($hide[$=$v.name]) = false 
      and $exists($hideFormats[$=$v.type]) = false 
      and $substringAfter($v.name, 'Id') != ''
  };

  $defaultView := {
    "name": "Default",
    "isDefault": true,
    "rowLimit": 500,
    "columns": $columns,
    "filters": $filters,
    "sort": []
  };

  $merge([
    $,
    {
      "views": [$defaultView],
      "query": {
        "api": $state.context.parameters.api,
        "model": $state.context.component.model.name,
        "fields": ["id"]
      }
    }
  ])
)

(
  $name := $state.context.component.model.name;
  $typeLabel := $startCase($name);
  $labelField := $state.context.component.labelField;

  $makeMutation := function($action) {
    'mutation ' & $upperFirst($action) & $name & '($payload: [' & $name & $upperFirst($action) & 'PayloadInput!]!) {
        mutation: ' & $action & $name & '(payload: $payload) { 
          id
          ' & $labelField & '
      }
    }'
  };

  $mutable := $coalesce([$state.context.component.model.metadata.mfgx.mutable, true]);
  $mutations := $state.context.component.model.metadata.mfgx.mutations;

  $mutations := {
    "create": $mutable and $coalesce([$mutations.create, true]),
    "update": $mutable and $coalesce([$mutations.update, true]),
    "delete": $mutable and $coalesce([$mutations.delete, true])
  };

  $isJoinTable := $state.context.component.name ~> $contains('JoinTable');

  [
    {
      "title": 'Search',
      "icon": {
        "icon": 'search',
        "variant": 'regular'
      },
      "buttonColor": 'primary',
      "color": 'primary',
      "action": {
        "navigation": {
          "submit": true
        }
      }
    },
    $mutations.create ? {
      "title": $isJoinTable ? 'Link' : 'Create',
      "icon": {
        "icon": $isJoinTable ? "link" : "plus",
        "variant": "regular"
      },
      "buttonColor": 'secondary',
      "action": [
        {
          "type": "form",
          "submitIcon": {
            "icon": $isJoinTable ? "link" : "plus",
            "variant": 'regular'
          },
          "title": ($isJoinTable ? 'Link a ' : 'Create a new ') & $typeLabel,
          "fields": [create[name != "id"]]
        },
        {
          "type": "mutation",
          "transforms": {
            "pre": '{
    "payload": {
      "create": data
    }
  }'
          },
          "api": $state.context.parameters.api,
          "mutation": $makeMutation('create'),
          "message": {
            "__transform":
              '"' & $typeLabel & ' " & mutation.' & $labelField & ' & " created successfully."'
          }
        },
        {
          "type": "navigation",
          "submit": true
        }
      ]    
    } : {
      "title": 'Create',
      "disabled": true,
      "icon": {
        "icon": "plus",
        "variant": "regular"
      }
    },
    $mutations.update ? {
      "title": 'Update',
      "disabled": $isJoinTable ? true : {
        "__transform": '$count(selectedRows) != 1'
      },
      "icon": 'pencil',
      "buttonColor": 'secondary',
      "action": [
        {
          "type": "form",
          "transforms": {
            "pre": 'selectedRows[0]'
          },
          "submitIcon": 'save',
          "title": {
            "__transform": '"Update ' & $typeLabel & ' " & selectedRows.label'
          },
          "fields": [update]
        },
        {
          "type": "mutation",
          "transforms": {
            "pre": '{
    "payload": selectedRows.{
      "where": {
        "id": id
      },
      "update": $$.data
    }
  }'
          },
          "api": $state.context.parameters.api,
          "mutation": $makeMutation('update'),
          "message": {
            "__transform":
              '($count(selectedRows) = 1 ? ("' & $typeLabel & ' " & selectedRows.' & $labelField & ') : $count(selectedRows) & " records") & " updated successfully."'
          }
        },
        {
          "type": "navigation",
          "submit": true
        }
      ]    
    } : {
      "title": 'Update',
      "disabled": true,
      "icon": 'pencil'
    },
    $mutations.delete ?   {
      "title": $isJoinTable ? 'Unlink' : 'Delete',
      "disabled": {
        "__transform": '$count(selectedRows) = 0'
      },
      "icon": {
        "icon": $isJoinTable ? 'unlink' : 'trash',
        "variant": 'solid'
      },
      "buttonColor": 'error',
      "action": [
        {
          "type": "confirmation",
          "buttonColor": 'error',
          "submitIcon": {
            "icon": $isJoinTable ? 'unlink' : 'trash',
            "variant": 'solid'
          },
          "message": {
            "__transform": ($isJoinTable ? '"Unlink "' : '"Delete "') & ' & ($count(selectedRows) = 1 ? ("' & $typeLabel & ' " & selectedRows.' & $labelField & ') : $count(selectedRows) & " records") & "?"'
          }
        },
        {
          "type": "mutation",
          "transforms": {
            "pre": '{
    "payload": selectedRows.{
      "where": {
          "id": id
        }
      }
    }'
          },
          "api": $state.context.parameters.api,
          "mutation": $makeMutation('delete'),
          "message": {
            "__transform":
              '($count(selectedRows) = 1 ? ("' & $typeLabel & ' " & selectedRows.' & $labelField & ') : $count(selectedRows) & " records") & " ' & ($isJoinTable ? "unlinked " : "deleted ") & 'successfully."'
          }
        },
        {
          "type": "navigation",
          "submit": true
        }
      ]    
    } : {
      "title": 'Delete',
      "disabled": true,
      "icon": {
        "icon": 'trash',
        "variant": 'solid'
      }
    }
  ]
)

(
  /* $state := {"context":context}; */

  $modelName := $state.context.component.model.name;

  $merge([
    $,
    {
      "updateAction": {
        "api": $state.context.parameters.api,
        "transforms": {
          "pre": '{
            "create": [
              $isNilOrEmpty(initialData.id) ? {
                "create": $merge([data,{"id": $metadata.urlParameters.id }])
              } : undefined
            ],
            "update": [
             $isNilOrEmpty(initialData.id)~>$not() ? {
                "where": {
                  "id": initialData.id
                },
                "update": data
              } : undefined
            ]
          }'
        },
        "mutation": 'mutation createUpdate' & $modelName & '($create: [' & $modelName & 'CreatePayloadInput!]!,$update: [' & $modelName & 'UpdatePayloadInput!]!) {
          create: create' & $modelName & '(payload: $create) {
            id
            ' & $state.context.component.labelField & '
          }
          update: update' & $modelName & '(payload: $update) {
            id
            ' & $state.context.component.labelField & '
          }
        }'
      },
      "query": {
        "api": $state.context.parameters.api,
        "model": $state.context.component.model.name,
        "fields": ["id"]
      },
      "parameters": [
        {
          "dataPath": 'filter.id._eq',
          "type": 'parameter',
          "parameterName": 'id'
        }
      ]
    }
  ]);
)

(
  $name := $state.context.component.model.name;
