(
  /* $state := {"context": context}; */

  $standardFields := [
    'id',
    'createdAt',
    'createdByUser',
    'createdByUserId',
    'dataChanges',
    'updatedAt',
    'updatedByUser',
    'updatedByUserId'
  ];

  /* A join model is a model with only two reference fields. */
  $getJoinProps := function($field, $model) {(

    $joinField := $filter($model.fields, function($v) {
      $not($exists($standardFields[$=$v.name]))
    });

    $joinField2 := $filter($joinfield, function($v){
      $v.type = 'ID!'
    });

    $count($joinField) = 4 and $count($joinField2) = 2 ? {
      "field": $joinField
    } : null
  )};

  $parseField := function($field) {(
    $baseTypeMatch := $match($field.type, /\[?(\w+)!?\]?!?/);
    $baseType := $baseTypeMatch.groups[0];

    $model := $executeTransform("getModelByName", 
      {
        "api": $state.context.parameters.api,
        "name": $baseType
      }
    );

    {
      "field": $field,
      "isList": $contains($field.type, "["),
      "baseType": $baseType,
      "baseTypeModel": $model,
      "joinProps": $getJoinProps($field, $model)
    }
  )}; 

  /* Parse field types. */
  $parsedFields := $map(model.fields, $parseField);

  /* Filter to only lists of reference types. */
  $referenceFields := $filter($parsedFields, function($field) {
    $field.isList and $field.baseTypeModel.kind = 'Reference' and $field.field.name != 'dataChanges'
  });

  $tabTables := $map($referenceFields, function($v) {
    {
      "type": "table",
      "name": $v.baseTypeModel.name & ($isNil($v.joinProps) ? "Nested" : "Join") & "Table",
      "tabTitle": $pluralize($startCase($v.baseTypeModel.name), 'en'),
      "model": $v.baseTypeModel,
      "labelField": $v.baseTypeModel.metadata.mfgx.labelField ? $v.baseTypeModel.metadata.mfgx.labelField : 'id',
      "parameterField": $v.field.metadata.mfgx.relation.fields.to
    }
  });

  $dataChangesTab := $exists(
    $filter($parsedFields, function($a) {
      $a.baseType = model.name & "DataChange"
     }
   )) ? 
  {
    "type": "dataChanges",
    "tabTitle": "Data Changes",
    "name": "DataChanges",
    "model": model,
    "labelField": model.metadata.mfgx.labelField ? model.metadata.mfgx.labelField : 'id'   
  } : undefined;

  $append([{
    "type": "form",
    "tabTitle": "Details",
    "name": model.name & "DetailForm",
    "model": model,
    "labelField": model.metadata.mfgx.labelField ? model.metadata.mfgx.labelField : 'id' 
  },$dataChangesTab], $tabTables)
)

