  screenVersion(where: { screenId:{ _eq: $screenId } }) {
    edges {
      node {
        number
      }
    }
  }
}

data.transform:
(
  $numbers := [$map([screenVersion.edges.node], function($node) {
    { "number": [$split($node.number, '.'), '0', '0', '0'][[0..2]].($coalesce([$parseNumber($), 0])) }
  })]^(number[0], number[1], number[2]);

  $lastNumber := [$last($numbers)];

  $nextNumber := $lastNumber 
      ? $join([$lastNumber.number[0], $lastNumber.number[1], $lastNumber.number[2] + 1].($string($)), '.') 
      : "0.0.1";

  $count(screenVersion.edges.node[number = $nextNumber]) > 0
    ? $throw("Unable to compute a unique version number.  Please ensure screen version numbers adhere to semantic versioning (i.e. 1.0.0).")
    : {
      "nextVersionNumber": $nextNumber
    }
)

